from pathlib import Path
r=Path(__file__).parent/'miniprogram'
s='''const {request,session,all,download,upload}=require('../../utils/api')
const titles={inventory:'库存与销售',harvest:'采收与产品溯源',finance:'成本与销售收益',weather:'天气中心',rules:'环境阈值与预警',guides:'农技资料',notifications:'消息与待办',reports:'台账报表',files:'附件管理',users:'账号管理',audit:'操作审计'}
const labels={crop:'作物',batch:'批次',grade:'等级',quantity:'数量（kg）',reserved:'预占（kg）',available:'可用（kg）',customer:'客户',price:'单价（元/kg）',amount:'金额（元）',status:'状态',source:'来源',org:'经营主体',name:'名称',username:'账号',role:'角色',district:'辖区',created_at:'时间',actor:'操作人',action:'操作',year:'年度',cost:'登记成本（元）',sales:'出库销售（元）',profit:'收支差额（元）',unallocated_cost:'未关联地块成本（元）',unallocated_sales:'未关联地块销售（元）',temperature_2m:'气温（℃）',relative_humidity_2m:'空气湿度（%）',precipitation:'降水（mm）',wind_speed_10m:'风速（km/h）',time:'天气时间',fetched_at:'读取时间',temperature_min:'温度下限',temperature_max:'温度上限',humidity_min:'空气湿度下限',humidity_max:'空气湿度上限',soil_min:'土壤湿度下限',soil_max:'土壤湿度上限',stage:'生长阶段',basis:'阈值依据',date:'日期',note:'说明',size:'大小（字节）',stock_id:'库存编号'}
function pairs(obj,keys){return (keys||Object.keys(obj)).filter(k=>labels[k]&&obj[k]!==undefined).map(k=>({label:labels[k],value:typeof obj[k]==='object'?JSON.stringify(obj[k]):String(obj[k])}))}
function card(row,title,keys){return {id:row.id,title:title||row.title||row.name||row.batch||row.username||'记录',demo:row.demo,details:pairs(row,keys),data:row}}
Page({data:{kind:'',title:'',user:null,rows:[],extra:[],summary:[],modules:[],moduleIndex:0,lands:[],landIndex:0,year:new Date().getFullYear(),includeDemo:false,busy:false,error:'',note:''},onLoad(o){this.kind=o.kind;this.setData({kind:o.kind,title:titles[o.kind]||'业务工作台'});wx.setNavigationBarTitle({title:this.data.title})},onShow(){this.load()},onPullDownRefresh(){this.load()},async load(){if(this.data.busy)return;this.setData({busy:true,error:'',rows:[],extra:[],summary:[],note:''});try{const user=await session();if(!user)return;this.setData({user});const k=this.kind;if(['finance','harvest','rules'].includes(k)&&user.role!=='farmer')throw new Error('该经营功能仅种植户账号可用');if(['users','audit'].includes(k)&&user.role!=='admin')throw new Error('该功能仅管理员可用');if(k==='inventory'){this.setData({rows:(await request('/stocks')).map(x=>card(x,x.crop+' / '+x.batch)),extra:(await request('/orders')).map(x=>card(x,'订单 #'+x.id+' · '+x.customer))})}else if(k==='harvest'){this.setData({rows:(await all('/records/harvest')).map(x=>card({...x.data,id:x.id,demo:x.demo,status:x.status},x.title)),extra:(await request('/traces')).map(x=>({...card({...x.snapshot,id:x.id},x.snapshot.crop+' / '+x.snapshot.batch),published:x.published,token:x.token}))})}else if(k==='finance'){const x=await request('/finance?year='+this.data.year+'&include_demo='+this.data.includeDemo);this.setData({summary:pairs(x,['year','cost','sales','profit','unallocated_cost','unallocated_sales']),rows:x.plots.map(p=>card({...p,id:p.plot_id},p.title)),extra:x.monthly.map(p=>card(p,p.month)),note:x.note})}else if(k==='weather'){const lands=await all('/records/lands');const i=Math.min(this.data.landIndex,Math.max(lands.length-1,0));this.setData({lands,landIndex:i,note:'室外天气与田间实测分别记录，不代表真实传感器采集。'});if(lands.length){const x=await request('/plots/'+lands[i].id+'/weather');this.setData({summary:pairs(x.current),note:x.source+' · '+(x.cached?'缓存数据':'即时查询')+' · '+x.fetched_at+'。室外天气不代表田间实测。'})}}else if(k==='rules'){this.setData({rows:(await request('/environment-rules')).map(x=>({...card({...x.data,id:x.id},x.title),status:x.status}))})}else if(k==='guides'){this.setData({rows:(await request('/crop-guides')).map((x,i)=>({...card({id:i},x.title),guide:x,details:[{label:'适用范围',value:x.scope},{label:'生长阶段',value:x.stages.join(' → ')},{label:'巡检要点',value:x.checks.join('；')},{label:'来源',value:x.source_title},{label:'说明',value:x.note}]}))})}else if(k==='notifications'){this.setData({rows:(await request('/notifications')).map((x,i)=>({...card({...x,id:i},x.title,['status']),module:x.module}))})}else if(k==='reports'){this.setData({modules:await request('/modules'),note:'报表注明数据来源与范围，导出操作保留审计记录。'})}else if(k==='files'){this.setData({rows:(await request('/files')).map(x=>card(x,x.name)),note:'单文件最大10MB，附件按经营主体和辖区隔离。'})}else if(k==='users'){this.setData({rows:(await request('/admin/users')).map(x=>({...card(x,x.name,['username','role','org','district']),active:x.active}))})}else if(k==='audit'){this.setData({rows:(await request('/admin/audit')).map((x,i)=>card({...x,id:i},x.action)),note:'完整审计详情可在 PC 工作台查看。'})}else throw new Error('该功能入口不存在')}catch(e){this.setData({error:e.message})}finally{this.setData({busy:false});wx.stopPullDownRefresh()}},edit(e){wx.navigateTo({url:'/pages/editor/index?kind='+e.currentTarget.dataset.kind})},inputYear(e){this.setData({year:e.detail.value})},demo(e){this.setData({includeDemo:e.detail.value})},land(e){this.setData({landIndex:Number(e.detail.value)});this.load()},module(e){this.setData({moduleIndex:Number(e.detail.value)})},async saveFile(e){if(this.data.busy)return;this.setData({busy:true,error:''});try{if(this.kind==='reports'){const m=this.data.modules[this.data.moduleIndex];if(!m)throw new Error('没有可导出的台账');const format=e.currentTarget.dataset.format;await download('/reports/'+m.id+'/'+format,m.title+'.'+format)}else if(this.kind==='finance'){const format=e.currentTarget.dataset.format;await download('/finance/export/'+format+'?year='+this.data.year+'&include_demo='+this.data.includeDemo,'成本收益.'+format)}else if(e.currentTarget.dataset.qr){await download('/traces/'+e.currentTarget.dataset.id+'/qr','溯源码.png')}else{const row=this.data.rows.find(x=>x.id===Number(e.currentTarget.dataset.id));await download('/files/'+row.id,row.title)}}catch(e){this.setData({error:e.message})}finally{this.setData({busy:false})}},action(e){if(this.data.busy)return;const id=Number(e.currentTarget.dataset.id),action=e.currentTarget.dataset.action;const content={ship:'确认实物已出库？操作会扣减库存。',cancel:'取消订单并释放预占库存？',stock:'确认该采收实际重量并入库？每条采收只能入库一次。',publish:'切换公开状态将公开或关闭经营主体、地块、采收批次和农事摘要，请先确认公开范围。',toggle:'确认切换该账号或规则的启停状态？'}[action];wx.showModal({title:'操作确认',content,success:async r=>{if(!r.confirm||this.data.busy)return;this.setData({busy:true,error:''});try{let path=this.kind==='inventory'?'/orders/'+id+'/'+action:this.kind==='harvest'?(action==='stock'?'/harvests/'+id+'/stock':'/traces/'+id+'/publish'):this.kind==='rules'?'/environment-rules/'+id+'/toggle':'/admin/users/'+id+'/toggle';await request(path,{method:'POST',data:{}});wx.showToast({title:'操作成功'});this.setData({busy:false});await this.load()}catch(e){this.setData({error:e.message,busy:false})}}})},notify(e){const row=this.data.rows.find(x=>x.id===Number(e.currentTarget.dataset.id));if(row.module==='planting-flow')wx.switchTab({url:'/pages/ai/index'});else wx.navigateTo({url:'/pages/records/index?module='+row.module})},source(e){const row=this.data.rows.find(x=>x.id===Number(e.currentTarget.dataset.id));wx.setClipboardData({data:row.guide.source})},upload(){if(this.data.busy)return;wx.chooseMessageFile({count:1,type:'file',extension:['pdf','png','jpg','jpeg','webp','txt','csv','xlsx','docx','zip'],success:async r=>{const file=r.tempFiles[0];if(file.size>10*1024*1024){this.setData({error:'单文件不能超过10MB'});return}this.setData({busy:true,error:''});try{await upload(file);wx.showToast({title:'上传成功'});this.setData({busy:false});await this.load()}catch(e){this.setData({error:e.message,busy:false})}},fail:()=>this.setData({error:'文件选择已取消或无法打开'})})}})
'''
p=r/'pages/service';p.mkdir(exist_ok=True)
(p/'index.js').write_text(s,encoding='utf-8')
(p/'index.json').write_text('{"navigationBarTitleText":"农知行 · 工作台","enablePullDownRefresh":true}',encoding='utf-8')
(p/'index.wxss').write_text('',encoding='utf-8')
(p/'index.wxml').write_text('''<view class="page"><view class="hero"><view class="title">{{title}}</view><view class="muted">{{user.org}}</view></view><view wx:if="{{error}}" class="error">{{error}}</view><view class="card"><button bindtap="load" loading="{{busy}}" disabled="{{busy}}">刷新</button><view wx:if="{{kind==='inventory' && user.role==='farmer'}}" class="actions"><button bindtap="edit" data-kind="stock">农产品入库</button><button bindtap="edit" data-kind="order">创建订单</button></view><button wx:if="{{kind==='harvest'}}" bindtap="edit" data-kind="harvest">登记关联采收</button><button wx:if="{{kind==='rules'}}" bindtap="edit" data-kind="rule">新增预警规则</button><button wx:if="{{kind==='users'}}" bindtap="edit" data-kind="user">新增账号</button><button wx:if="{{kind==='files'}}" bindtap="upload" disabled="{{busy}}">上传附件</button><block wx:if="{{kind==='finance'}}"><view class="label">核算年度</view><input type="number" value="{{year}}" bindinput="inputYear" placeholder="例如：2026"/><view class="row"><view class="label">包含演示样本</view><switch checked="{{includeDemo}}" bindchange="demo" color="#246b47"/></view></block><picker wx:if="{{kind==='weather' && lands.length}}" range="{{lands}}" range-key="title" value="{{landIndex}}" bindchange="land"><view class="picker">{{lands[landIndex].title}} ↓</view></picker><picker wx:if="{{kind==='reports'}}" range="{{modules}}" range-key="title" value="{{moduleIndex}}" bindchange="module"><view class="picker">{{modules[moduleIndex].title||'暂无台账'}} ↓</view></picker><view wx:if="{{kind==='reports'||kind==='finance'}}" class="actions"><button bindtap="saveFile" data-format="xlsx" disabled="{{busy}}">下载 Excel</button><button bindtap="saveFile" data-format="pdf" disabled="{{busy}}">下载 PDF</button></view><view wx:if="{{note}}" class="note">{{note}}</view></view><view wx:if="{{summary.length}}" class="card"><view class="kv" wx:for="{{summary}}" wx:key="label"><text class="key">{{item.label}}</text><text class="value">{{item.value}}</text></view></view><view class="card" wx:for="{{rows}}" wx:key="id"><view class="row"><view class="name">{{item.title}}</view><text wx:if="{{item.demo}}" class="badge demo">演示</text></view><view class="kv" wx:for="{{item.details}}" wx:for-item="field" wx:key="label"><text class="key">{{field.label}}</text><text class="value">{{field.value}}</text></view><button wx:if="{{kind==='files'}}" bindtap="saveFile" data-id="{{item.id}}" disabled="{{busy}}">下载 / 预览</button><button wx:if="{{kind==='harvest' && item.data.status!=='已入库'}}" bindtap="action" data-id="{{item.id}}" data-action="stock" disabled="{{busy}}">确认采收入库</button><button wx:if="{{kind==='rules'}}" bindtap="action" data-id="{{item.id}}" data-action="toggle" disabled="{{busy}}">{{item.status==='启用'?'停用规则':'启用规则'}}</button><button wx:if="{{kind==='users'}}" bindtap="action" data-id="{{item.id}}" data-action="toggle" disabled="{{busy}}">{{item.active?'停用账号':'启用账号'}}</button><button wx:if="{{kind==='guides'}}" bindtap="source" data-id="{{item.id}}">复制官方资料链接</button><button wx:if="{{kind==='notifications'}}" bindtap="notify" data-id="{{item.id}}">进入处理</button></view><view wx:if="{{extra.length}}" class="section-title">{{kind==='inventory'?'销售订单':kind==='harvest'?'产品溯源':'月度收支'}}</view><view class="card" wx:for="{{extra}}" wx:key="id"><view class="name">{{item.title}}</view><view class="kv" wx:for="{{item.details}}" wx:for-item="field" wx:key="label"><text class="key">{{field.label}}</text><text class="value">{{field.value}}</text></view><view wx:if="{{kind==='inventory' && item.data.status==='待出库' && user.role==='farmer'}}" class="actions"><button bindtap="action" data-id="{{item.id}}" data-action="ship" disabled="{{busy}}">确认出库</button><button bindtap="action" data-id="{{item.id}}" data-action="cancel" disabled="{{busy}}">取消订单</button></view><block wx:if="{{kind==='harvest'}}"><view class="note">公开状态：{{item.published?'已公开':'未公开'}}。二维码沿用现有 PC 地址，实体手机扫码需设置可访问地址。</view><view class="actions"><button bindtap="action" data-id="{{item.id}}" data-action="publish" disabled="{{busy}}">{{item.published?'关闭公开':'确认公开'}}</button><button bindtap="saveFile" data-id="{{item.id}}" data-qr="{{true}}" disabled="{{busy}}">查看溯源码</button></view></block></view><view wx:if="{{!rows.length && !extra.length && !summary.length && !busy && kind!=='reports'}}" class="card empty">暂无数据</view></view>''',encoding='utf-8')
print('经营、天气、附件与报表页面已生成')
